  function lazyProp(obj, key, compute) {
    Object.defineProperty(obj, key, {
      enumerable: true,
      configurable: true,
      get() {
        const v = compute();
        Object.defineProperty(this, key, { value: v, writable: true, enumerable: true, configurable: true });
        return v;
      },
    });
    return obj;
  }
